<template>
  <div class="step_container">
    <div class="itemsArea">
      <div class="control_panel">

        <!-- Primary controls -->
        <div class="control-group primary">
          <div class="control-item">
            <div class="control-icon play" @click="control_play">
              <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                <path d="M8 5v14l11-7-11-7z" />
              </svg>

            </div>
            <div class="control-label">Normal<br>Simulation</div>
          </div>

          <div class="control-item">
            <div class="control-icon stop">
              <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                <rect x="6" y="6" width="12" height="12" />
              </svg>

            </div>
            <div class="control-label">Stop<br>Simulation</div>
          </div>
        </div>

        <!-- Secondary controls -->
        <div class="control-group secondary">
          <div class="control-item">
            <div class="control-icon step">
              <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                <path d="M5 4l8 8-8 8V4z" />
                <rect x="15" y="4" width="3" height="16" />
              </svg>
            </div>
            <div class="control-label">Step by Step</div>
          </div>

          <div class="control-item">
            <div class="control-icon slow">
              <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                <path d="M6 5l10 7-10 7V5z" />
              </svg>

            </div>
            <div class="control-label">Slow Motion</div>
          </div>

          <div class="control-item">

            <div class="control-icon pause">
              <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                <rect x="6" y="5" width="4" height="14" />
                <rect x="14" y="5" width="4" height="14" />
              </svg>
            </div>

            <div class="control-label">Pause</div>
          </div>
        </div>

      </div>


      <!-- ✅ Native Drop 영역 -->
      <div v-show="uploadMode === 'file'" class="upload-wrapper">
        <div ref="nativeDropZone" class="native-drop-zone" @click="triggerNativeFile"
          @dragover.prevent="dragging = true" @dragleave.prevent="dragging = false" @drop.prevent="onNativeDrop"
          :class="{ active: dragging }">
          <!-- ✅ 파일명 / 안내문구 교체 -->
          <template v-if="fileName">
            <div class="file-display">
              <v-icon color="primary" size="20">mdi-file</v-icon>
              <span class="ml-2"> {{ fileName }} ({{ fileSize }}) </span>
              <v-btn icon variant="text" color="error" size="x-small" class="ml-1" @click.stop="clearFile">
                <v-icon size="16">mdi-close</v-icon>
              </v-btn>
            </div>
          </template>

          <template v-else>
            <p>
              📂 파일을 이 영역으로 <strong>끌어오거나</strong><br />클릭해서
              선택하세요
            </p>
          </template>

          <!-- 숨김 input -->
          <input ref="nativeFileInput" type="file" accept=".csv,.xlsx,.txt, .json" style="display: none"
            @change="onNativeFileChange" />
        </div>
      </div>

      <div :class="['gray-panel', { disabled: uploadMode === 'file' }]">
        <v-row>
          <v-col class="pa-0">
            <v-card class="demandArea">
              <v-card-title>수요지역</v-card-title>
              <v-card-text>
                <v-text-field label="주소 검색" variant="outlined" v-model="demandArea" placeholder="주소를 검색하세요" readonly
                  prepend-inner-icon="mdi-magnify" @click="openPostcode" color="primary" class="demand-input"
                  hide-details density="compact" />
              </v-card-text>
            </v-card>
          </v-col>
        </v-row>

        <v-row>
          <v-col class="pa-0">
            <v-card>
              <v-card-title>송배전망</v-card-title>
              <div class="buttons">
                <v-btn class="tool-item" v-for="btn in transStore" :key="btn.id" draggable="true"
                  @dragstart="startDrag($event, btn)" variant="flat">
                  <div class="tool-content">
                    <img :src="getIconByLabel(btn.label)" class="tool-icon" alt="" />
                    <div class="tool-label">
                      {{ btn.label }}
                    </div>
                  </div>
                </v-btn>
              </div>
              <div class="buttons">
                <v-btn class="tool-item" v-for="btn in distribStore" :key="btn.id" draggable="true"
                  @dragstart="startDrag($event, btn)" variant="flat">
                  <div class="tool-content">
                    <img :src="getIconByLabel(btn.label)" class="tool-icon" alt="" />
                    <div class="tool-label">
                      {{ btn.label }}
                    </div>
                  </div>
                </v-btn>


              </div>
            </v-card>
          </v-col>
        </v-row>

        <v-row>
          <v-col class="pa-0">
            <v-card>
              <v-card-title>NWAs</v-card-title>
              <div class="buttons">
                <v-btn class="tool-item" v-for="btn in nwasStore" :key="btn.id" draggable="true"
                  @dragstart="startDrag($event, btn)" variant="flat">
                  <div class="tool-content">
                    <img :src="getIconByLabel(btn.label)" class="tool-icon" alt="" />
                    <div class="tool-label">
                      {{ btn.label }}
                    </div>
                  </div>
                </v-btn>
              </div>

            </v-card>
          </v-col>
        </v-row>

      </div>

      <div class="treeBottom">
        <v-card>
          <v-card-title>
            Case 별 비용산출
          </v-card-title>

          <v-card-text>
            <!-- Case 라디오 버튼 -->
            <v-radio-group v-model="selectedCaseId" hide-details class="case-radio-group">
              <v-radio v-for="c in case_definitions" :key="c.id" :label="c.name" :value="c.id" />
            </v-radio-group>

            <v-divider class="my-2" />

            <!-- Case 설명 -->
            <div v-if="selectedCaseInfo">
              <h4>{{ selectedCaseInfo.name }}</h4>
              <p>{{ selectedCaseInfo.description }}</p>
            </div>

            <div v-else class="text-muted">
              Case를 선택하면 설명이 표시됩니다.
            </div>
          </v-card-text>
        </v-card>
      </div>


    </div>

    <div class="arrangeArea">

      <div class="scrollCanvas">

        <div class="drop-zones">
          <div v-for="zone in dropZones" :key="zone.id" class="drop-zone" :class="{ 'invalid-zone': !zone.isValid }"
            @dragover="onDragOver($event, zone.id)" @dragleave="resetZoneColors" @drop="onDrop($event, zone.id)">
            <ul class="list-unstyled m-0 p-0 zone-grid">
              <li v-for="item in zone.items" :key="item.id" class="zone-item">
                <div class="tool-item-like" :class="[
                  getToolBorderClass(item.id),
                  { 'topology-selected': isTopologySelected(zone.caseIndex) }
                ]" draggable="true" :data-node-uid="item.uniqueId" :data-case-index="zone.caseIndex">
                  <!-- 🔵 화살표 전용 -->
                  <div class="tool-anchors">
                    <span class="anchor arrow top"></span>
                    <span class="anchor arrow right"></span>
                    <span class="anchor arrow bottom"></span>
                    <span class="anchor arrow left"></span>
                  </div>
                  <div class="tool-content">
                    <img :src="getIconByLabel(item.label)" class="tool-icon" alt="" />

                    <div class="tool-label">
                      {{ item.label }}
                    </div>
                  </div>
                </div>
              </li>
            </ul>
          </div>
        </div>

        <!-- 🔥 계통 연결선 SVG -->
        <svg class="connection-svg" :width="svgWidth" :height="svgHeight" :viewBox="`0 0 ${svgWidth} ${svgHeight}`">
          <path v-for="(p, idx) in sortedSvgPaths" :key="idx" :d="p.d" :stroke="getStrokeColor(p.caseIndex)"
            :stroke-width="isTopologySelected(p.caseIndex) ? 4 : 2" fill="none" />
        </svg>

      </div>
    </div>

    <!-- 오른쪽: Tree + 고정 카드 -->
    <div class="tree-caseArea">

      <!-- 위: Tree 카드 -->
      <v-card class="treeCard">
        <v-card-title class="treeCardTitle">
          <span>Topologys</span>

          <!-- 구조 요약 정보 -->
          <span class="topology-meta">
            {{ treeItems.length }}
          </span>
        </v-card-title>

        <v-card-text class="treeCardBody">
          <TopologyTree :items="treeItems" :selectedTopologies="selectedTopologies"
            @toggle-topology="onToggleTopology" />
        </v-card-text>
      </v-card>


    </div>

  </div>

  <v-dialog v-model="showDialog" max-width="400px">
    <v-card>
      <v-card-title> 알림 </v-card-title>
      <v-card-text> {{ dialogText }} </v-card-text>
      <v-card-actions>
        <v-btn color="primary" @click="showDialog = false">닫기</v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>

  <div v-if="isLoading" class="loading-overlay">
    <div class="spinner"></div>
    <p>파일을 불러오는 중입니다…</p>
  </div>

</template>


<script setup>
import { ref, watch, computed, nextTick, onMounted } from "vue";
import { useDropZoneStore } from "../store/dropZoneStore.js";
import { useItemStore } from "../store/itemStore.js";
import { useProgressStore } from "../store/progressStore.js";
import { useTopologyStore } from "../store/topologyStore.js";
import { useUiStore } from "../store/uiStore.js";
import { storeToRefs } from "pinia";
import { useRouter } from "vue-router";
import TopologyTree from "@/components/TopologyTree.vue";

const uiStore = useUiStore()

const store = useDropZoneStore();
const topologyStore = useTopologyStore();

const { dropZones } = storeToRefs(store);

const itemStore = useItemStore();
const { transStore } = storeToRefs(itemStore);
const { distribStore } = storeToRefs(itemStore);
const { nwasStore } = storeToRefs(itemStore);

const startItem = ref(null);
const maxTopology = ref(0);

const progressStore = useProgressStore();
const router = useRouter();
const demandArea = ref("");

var dialogText = ref("");
const showDialog = ref(false);

const uploadMode = ref("manual");
const nativeFileInput = ref(null);
const nativeDropZone = ref(null);
const dragging = ref(false);
const fileName = ref("");
const fileSize = ref("");

const isLoading = ref(false);

const selectedCaseId = ref(null);

const svgPaths = ref([])
const svgWidth = ref(0)
const svgHeight = ref(0)

const selectedTopologies = ref(new Set())

const icon_label = {
  원전: "Nuclear_power.png",
  석탄화력: "coal_fired_power.png",
  가스복합: "gas_combined_power.png",
  소수력: "small_hydropower.png",
  '765kV': "electricity-tower_2628822.png",
  '345kV': "electricity-tower_2628822.png",
  '154kV': "electricity-tower_2628822.png",
  '22.9kV': "electricity-tower_2628822.png",
  태양광: "solar-energy_2729361.png",
  풍력: "turbine_7294935.png",
  해상풍력: "eolian_12470907.png",
  ESS: "battery_17949309.png",
  EV: "electric-car_3444059.png",
  EVC: "vehicle_15533381.png",
  DR: "motivation_17146362.png",
  VPP: "transformation_8044393.png",
  수요지역: "shop_551347.png",
};

const case_definitions = [
  {
    id: "CASE_A",
    name: "Case A 계통접속기준형",
    description: "ESS와 DR을 함께 적용하여 피크 저감과 운영 유연성을 확보하는 시나리오입니다.",
    filePath: "../TopologyList/case1_계통접속기준형.txt"
  },
  {
    id: "CASE_B",
    name: "Case B 예비력 요구형",
    description: "ESS만을 활용하여 충방전 제어로 비용을 절감하는 시나리오입니다.",
    filePath: "../TopologyList/case2_예비력 요구형.txt"
  },
  {
    id: "CASE_C",
    name: "Case C 입력용량 제한형",
    description: "태양광 발전과 ESS를 연계하여 자가소비를 극대화하는 시나리오입니다.",
    filePath: "../TopologyList/case3_입력 용량 제한형.txt"
  },
  {
    id: "CASE_D",
    name: "Case D 부하완충 중심형",
    description: "설비 투자 없이 부하 이동 전략으로 비용을 절감하는 시나리오입니다.",
    filePath: "../TopologyList/case4_부하 완충 중심형.txt"
  },
  {
    id: "CASE_E",
    name: "Case E 최적형",
    description: "설비 투자 없이 부하 이동 전략으로 비용을 절감하는 시나리오입니다.",
    filePath: "../TopologyList/최종안.txt"
  },
];

const onToggleTopology = (topologyIndex, checked) => {
  if (checked) {
    selectedTopologies.value.add(topologyIndex)
  } else {
    selectedTopologies.value.delete(topologyIndex)
  }

  selectedTopologies.value = new Set(selectedTopologies.value)
}

const getStrokeColor = (caseIndex) => {

  return selectedTopologies.value.has(caseIndex)
    ? "#2563eb"   // 선택된 topology (강조)
    : "#cbd5e1"   // 비선택 (연한 회색)
}



const isTopologySelected = (caseIndex) => {
  return selectedTopologies.value.has(caseIndex)
}


const selectedCaseInfo = computed(() => {
  console.log("case 선택함")
  return case_definitions.find(c => c.id === selectedCaseId.value) || null;
});


watch(
  selectedCaseInfo,
  async (caseInfo, prevCaseInfo) => {
    if (!caseInfo) return
    if (caseInfo.id === prevCaseInfo?.id) return

    // 🔑 case 진짜 변경된 경우만
    selectedTopologies.value = new Set()

    try {
      await applyCaseFile(caseInfo)
    } catch (e) {
      console.error("case 적용 실패", e)
    }
  },
  { immediate: false }
)


const applyCaseFile = async (caseInfo) => {
  if (!caseInfo?.filePath) return

  const dropZoneStore = useDropZoneStore()

  isLoading.value = true;

  try {
    // 🔥 Case에 정의된 파일 경로로 로드
    const content = await fetch(caseInfo.filePath).then(r => r.text())

    const clean = content.replace(/^\uFEFF/, "")
    const parsed = JSON.parse(clean)

    if (!Array.isArray(parsed)) return

    // 🔥 topology 반영
    const enrichedTopology =
      await enrichTopologyWithCoordinates(parsed)

    topologyStore.topologyList = enrichedTopology

    // 🔥 dropZone 반영
    const dz = convertTopologyToDropZone(enrichedTopology)
    dropZoneStore.dropZones = dz

    await delay(500)


    isLoading.value = false;
  } catch (e) {
    console.error("Case 파일 적용 실패", e)
  } finally {
    uiStore.stopLoading()
  }
}


const icons = require.context(
  "@/assets/icons",
  false,
  /\.png$/
);

const getIconByLabel = (label) => {
  if (!label) return null;

  const normalizedLabel = label.replace(/-\w+$/, "");

  const file = icon_label[normalizedLabel];
  if (!file) return null;

  return icons(`./${file}`);
};

const treeItems = computed(() => {
  const list = topologyStore.topologyList;
  if (!Array.isArray(list)) return [];

  return list.map((topology, index) => ({
    id: `topology-${index}`,
    name: `Topology ${index + 1}`,
    type: "topology",

    children: topology.map((node, idx) => ({
      id: `topology-${index}-node-${idx}`,
      name: node.label,
      type: "element",
      raw: node,

      // 🔥 property 단위 그룹핑
      children: (node.property || []).map((prop, pIdx) => {
        const groupName =
          prop.name && prop.name.trim() !== ""
            ? prop.name
            : "기본속성"; // ✅ 타이틀 없는 경우

        return {
          id: `topology-${index}-node-${idx}-prop-${pIdx}`,
          name: groupName,
          type: "property-group",
          raw: prop,

          // 🔥 실제 값 노드
          children: (prop.values || []).map((v, vIdx) => ({
            id: `topology-${index}-node-${idx}-prop-${pIdx}-val-${vIdx}`,
            name: `${v.name ?? "값"} : ${formatValueWithUnit(v)}`,
            type: "property",
            raw: v,
            children: []
          }))
        };
      })
    }))
  }));
});

const formatValueWithUnit = (v) => {
  if (v == null) return "-";
  if (v.unit) return `${v.data} ${v.unit}`;
  return `${v.data}`;
};


async function control_play() {



  console.log("step1 DropZones : ", JSON.stringify(dropZones.value));

  if (isStep1Completed()) {
    try {
      // 🔥 1. 로딩 먼저
      uiStore.startLoading()

      // 👀 Step1 UI 변화가 보이도록 잠깐 유지
      await delay(800)

      // 🔥 4. step3
      progressStore.setCurrentStep(3)
      progressStore.stepConditions["step3"] = true
      router.push("/step3")
      await delay(2000)

      // 🔥 5. step4
      progressStore.setCurrentStep(4)
      progressStore.stepConditions["step4"] = true
      router.push("/step4")
      await delay(1000)

      // 🔥 6. 로딩 종료 → 결과 노출
      uiStore.stopLoading()

    } catch (err) {
      console.error(err)
      uiStore.stopLoading()
    }
  }
}

const delay = (ms) => new Promise(res => setTimeout(res, ms))

// X버튼 초기화
function clearFile() {
  fileName.value = "";
  fileSize.value = "";
  if (nativeFileInput.value) nativeFileInput.value.value = "";
}

function convertTopologyToDropZone(topologyList) {
  const dropZones = [
    { id: 1, name: "발전소", items: [], isValid: true },
    { id: 2, name: "765kV", items: [], isValid: true },
    { id: 3, name: "345kV", items: [], isValid: true },
    { id: 4, name: "154kV", items: [], isValid: true },
    { id: 5, name: "22.9kV", items: [], isValid: true },
    { id: 6, name: "수요지역", items: [], isValid: true },
    { id: 7, name: "NWAs", items: [], isValid: true },
  ];

  topologyList.forEach((group) => {
    if (!Array.isArray(group)) return;

    group.forEach(item => {
      if (!item || item.id == null) return;

      const zone = dropZones.find(z => z.id === Number(item.id));
      if (!zone) return;

      // 🔑 topology 소속 정보 추가
      zone.items.push({
        ...item,
      });
    });
  });

  // label 기준 중복 제거 (주의: caseIndex 다른 건 유지됨)
  dropZones.forEach(zone => {
    zone.items = zone.items.filter(
      (item, index, self) =>
        index === self.findIndex(
          i => i.label === item.label && i.caseIndex === item.caseIndex
        )
    );
  });

  return dropZones;
}


async function enrichTopologyWithCoordinates(topologyList) {
  for (const group of topologyList) {
    if (!Array.isArray(group)) continue;

    for (const item of group) {
      if (!item || item.id !== 6) continue; // 수요지역만

      if (item.lat !== 0 && item.lng !== 0) continue;

      const address = item.property
        ?.find(p => p.name === "수요지역정보")
        ?.values?.find(v => v.name === "주소")
        ?.data;

      if (!address) continue;

      try {
        const { lat, lng } = await getCoordinatesFromAddress(address);
        item.lat = lat;
        item.lng = lng;
      } catch (e) {
        console.warn("수요지역 위경도 변환 실패:", address, e);
      }
    }
  }

  return topologyList;
}

const getCoordinatesFromAddress = (address) => {

  return new Promise((resolve, reject) => {
    let geocoder = new window.google.maps.Geocoder();

    geocoder.geocode({ address }, (results, status) => {
      if (status === "OK" && results[0]) {
        const location = results[0].geometry.location;
        resolve({ lat: location.lat(), lng: location.lng() });
      } else {
        reject(status);
      }
    });
  });
};


// 주소검색
const openPostcode = () => {
  new window.daum.Postcode({
    oncomplete: function (data) {
      demandArea.value = data.address;
    },
  }).open();
};

// 드래그 시작 시 실행
const startDrag = (event, item) => {
  event.dataTransfer.effectAllowed = "move";
  event.dataTransfer.setData("draggedItem", JSON.stringify(item));
  startItem.value = item;
};

// 아이템 배치완료
const onDrop = (event, zoneId) => {
  const draggedItem = JSON.parse(event.dataTransfer.getData("draggedItem"));

  store.addItemToZone(zoneId, draggedItem);
  resetZoneColors();
  startItem.value = null;
};

// 해당 열 확인
const onDragOver = (event, zoneId) => {
  event.preventDefault();

  if (!startItem.value) return;

  const isValid = zoneId === startItem.value.id;

  event.dataTransfer.dropEffect = isValid ? "move" : "none";

  dropZones.value.forEach((zone) => {
    zone.isValid = zone.id === startItem.value.id;
  });
};

const resetZoneColors = () => {
  dropZones.value.forEach((zone) => (zone.isValid = true));
};


// 모든 dropzone에 하나 이상의 값이 저장되었을 때
watch(
  dropZones,
  (newZones) => {
    //  765(Zone ID: 2)를 제외한 모든 Zone이 비어있지 않은지 확인
    const relevantZones = newZones.filter((zone) => zone.id !== 2);

    const allFilled = relevantZones.every((zone) => zone.items.length > 0);

    if (allFilled) {
      //  maxTopology = (765 포함) 모든 zone의 items 개수 곱하기
      maxTopology.value = newZones.reduce(
        (product, zone) => product * (zone.items.length || 1), //  비어있는 zone은 1로 처리
        1
      );
    } else {
      maxTopology.value = 0;
    }
  },
  { deep: true, immediate: true }
);


// 완료 조건 함수
const isStep1Completed = () => {
  // 1. DropZoneStore에서 수요지역 데이터 가져오기 (ID 6)
  const demandZone = dropZones.value.find((zone) => zone.id === 6);
  const hasDemandData = demandZone?.items?.length > 0; // 안전한 데이터 접근 방식

  if (!hasDemandData) {
    dialogText = "수요지역 위치와 용량을 입력하세요.";
    showDialog.value = true;
    return false;
  }

  // 2. 765를 제외한 모든 dropZone이 비어있지 않은지 확인
  const relevantZones = dropZones.value.filter((zone) => zone.id !== 2);
  const allFilled = relevantZones.every((zone) => zone.items.length > 0);

  if (!allFilled) {
    dialogText = "모든 DropZone에 아이템을 배치해야 합니다. (765 제외)";
    showDialog.value = true;
    return false;
  }

  return true; // 모든 조건을 충족하면 true 반환
};


const getToolBorderClass = (id) => {
  return {
    'border-blue': id === 1,
    'border-green': id >= 2 && id <= 5,
    'border-orange': id === 6,
    'border-purple': id === 7,
  }
}


const buildConnectionsPerCase = (topologyList) => {
  if (!Array.isArray(topologyList)) return []

  const allConnections = []

  topologyList.forEach((caseNodes, caseIndex) => {
    if (!Array.isArray(caseNodes)) return

    // id → node
    const nodeMap = new Map()
    caseNodes.forEach(node => {
      nodeMap.set(node.id, node)
    })

    let prev = null

    for (let id = 1; id <= 7; id++) {
      const cur = nodeMap.get(id)
      if (!cur) continue

      if (prev) {
        allConnections.push({
          caseIndex,              // 🔥 이게 핵심
          fromStageId: prev.id,
          toStageId: cur.id,
          fromUid: prev.uniqueId,
          toUid: cur.uniqueId,
          fromLabel: prev.label,
          toLabel: cur.label
        })
      }

      prev = cur
    }
  })

  return allConnections
}


const topologyConnections = ref([])

watch(
  () => topologyStore.topologyList,
  (newTopology) => {
    const connections = buildConnectionsPerCase(newTopology)

    topologyConnections.value = connections

  },
  { deep: true, immediate: true }
)


const getNodeCenterByUid = (uid) => {
  const el = document.querySelector(`[data-node-uid="${uid}"]`)
  const area = document.querySelector(".arrangeArea")
  if (!el || !area) return null

  const rect = el.getBoundingClientRect()
  const areaRect = area.getBoundingClientRect()

  return {
    x:
      rect.left
      - areaRect.left
      + rect.width / 2
      + area.scrollLeft,

    y:
      rect.top
      - areaRect.top
      + rect.height / 2
      + area.scrollTop
  }
}


const makeElbowPath = (from, to) => {
  const midX = (from.x + to.x) / 2

  return `
    M ${from.x} ${from.y}
    L ${midX} ${from.y}
    L ${midX} ${to.y}
    L ${to.x} ${to.y}
  `
}

const buildSvgLines = () => {
  const paths = []

  topologyStore.topologyList.forEach((caseNodes, caseIndex) => {
    for (let i = 0; i < caseNodes.length - 1; i++) {
      const fromNode = caseNodes[i]
      const toNode = caseNodes[i + 1]

      const from = getNodeCenterByUid(fromNode.uniqueId)
      const to = getNodeCenterByUid(toNode.uniqueId)

      if (!from || !to) continue

      paths.push({
        d: makeElbowPath(from, to),

        /* 🔑 이 줄이 없어서 undefined 였음 */
        caseIndex
      })
    }
  })

  svgPaths.value = paths
}

watch(
  topologyConnections,
  () => {
    nextTick(() => {
      buildSvgLines()
    })
  },
  { deep: true }
)


window.addEventListener("resize", buildSvgLines)

const updateSvgSize = () => {
  const area = document.querySelector(".arrangeArea")
  if (!area) return

  svgWidth.value = area.scrollWidth
  svgHeight.value = area.scrollHeight
}


onMounted(() => {
  const area = document.querySelector(".arrangeArea")
  if (!area) return

  area.addEventListener("scroll", () => {
    updateSvgSize()
    buildSvgLines()
  })
  window.addEventListener("resize", buildSvgLines)

  nextTick(() => {
    updateSvgSize()
    buildSvgLines()
  })
})

const sortedSvgPaths = computed(() => {
  // 🔑 1단계: ref 자체 가드
  if (!selectedTopologies.value) {
    return svgPaths.value
  }

  const selected = selectedTopologies.value

  // 🔑 2단계: Set인지 가드 (안전장치)
  if (!(selected instanceof Set)) {
    return svgPaths.value
  }

  return [...svgPaths.value].sort((a, b) => {
    const aSelected = selected.has(a.caseIndex)
    const bSelected = selected.has(b.caseIndex)

    if (aSelected && !bSelected) return 1
    if (!aSelected && bSelected) return -1
    return 0
  })
})


</script>


