<template>
  <div class="result-page">
    <!-- 상단 타이틀 -->
    <div class="header">
      <h2>Simulation 결과</h2>
    </div>

    <!-- ✅ 상단 메뉴 (토글형) -->
    <div class="menu-bar">
      <div class="menu-title" :class="{ active: selectedTab === 'cost' }" @click="selectedTab = 'cost'">
        구축 및 편익 비용
      </div>

      <div class="menu-title" :class="{ active: selectedTab === 'carbon' }" @click="selectedTab = 'carbon'">
        연간 탄소배출량
      </div>
    </div>

    <!-- ✅ 콘텐츠 영역 -->
    <v-container class="content-container" fluid>
      <!-- [탭1] 구축 및 편익 비용 -->
      <v-row v-show="selectedTab === 'cost'">
        <!-- 좌측: 그래프 -->
        <v-col cols="7">
          <v-card class="graph-card" outlined>
            <v-row class="align-center mb-2">
              <v-col cols="auto">
                <v-select v-model="selectedGroupIndex" :items="groupOptions" item-title="title" item-value="value"
                  label="Topology List" density="compact" variant="outlined" hide-details style="width: 200px" />
              </v-col>
              <!-- ✅ 선택된 Topology 경로 표시 -->
              <v-col class="text-grey text-h6">
                <p v-for="(node, nodeIndex) in getSelectedList" :key="node.uniqueId || nodeIndex"
                  class="d-inline selectedList">
                  {{ node.label }}
                  <span v-if="nodeIndex < getSelectedList.length - 1">
                    {{
                      (() => {
                        const current = node.id;
                        const next = getSelectedList[nodeIndex + 1]?.id;
                        const hasDemandNode = getSelectedList.some(
                          (n) => n.id === 6
                        );
                        if (!hasDemandNode) return " ▶ ";
                        const demandIndex = getSelectedList.findIndex(
                          (n) => n.id === 6
                        );
                        return nodeIndex < demandIndex ? " ▶ " : " ◀ ";
                      })()}} </span>
                </p>
              </v-col>
            </v-row>

            <v-row>
              <v-col cols="6">
                <h4 class="chart-title">
                  배전망 - NWAs 구축 및 편익 비용 비교
                </h4>
                <canvas ref="barChart" height="220"></canvas>
              </v-col>
              <v-col cols="6">
                <h4 class="chart-title">배전망 - NWAs 구축 비용 비율</h4>
                <canvas ref="doughnutChart" height="220"></canvas>
              </v-col>
            </v-row>
          </v-card>
        </v-col>

        <!-- 우측: 데이터 테이블 -->
        <v-col cols="5">
          <v-card class="table-card" outlined>
            <div class="table-header">
              <span>구분</span>
              <span class="unit-label">단위 : 원</span>
            </div>
            <v-data-table :headers="tableHeaders" :items="tableItems" :items-per-page="-1" hide-default-footer
              density="compact" virtual-scroll="false" style="max-height: none; overflow: visible">
              <template v-slot:item="{ item }">
                <tr>
                  <td class="text-left font-weight-bold category-col">
                    {{ item.category }}
                  </td>
                  <td v-for="(topology, idx) in topologyList" :key="idx" class="text-right">
                    {{ item[`list${idx + 1}`] }}
                  </td>
                </tr>
              </template>
            </v-data-table>
          </v-card>
        </v-col>
      </v-row>

      <!-- [탭2] 탄소배출량 -->
      <v-row v-show="selectedTab === 'carbon'">
        <!-- 좌측: 그래프 -->
        <v-col cols="7">
          <v-card class="graph-card" outlined>
            <v-row class="align-center mb-2">
              <v-col cols="auto">
                <v-select v-model="selectedGroupIndex" :items="groupOptions" item-title="title" item-value="value"
                  label="Topology List" density="compact" variant="outlined" hide-details style="width: 200px" />
              </v-col>

              <!-- ✅ 선택된 Topology 경로 표시 -->
              <v-col class="text-grey text-h6">
                <p v-for="(node, nodeIndex) in getSelectedList" :key="node.uniqueId || nodeIndex"
                  class="d-inline selectedList">
                  {{ node.label }}
                  <span v-if="nodeIndex < getSelectedList.length - 1">
                    {{
                      (() => {
                        const current = node.id;
                        const next = getSelectedList[nodeIndex + 1]?.id;
                        const hasDemandNode = getSelectedList.some(
                          (n) => n.id === 6
                        );
                        if (!hasDemandNode) return " ▶ ";
                        const demandIndex = getSelectedList.findIndex(
                          (n) => n.id === 6
                        );
                        return nodeIndex < demandIndex ? " ▶ " : " ◀ ";
                      })()}} </span>
                </p>
              </v-col>
            </v-row>

            <v-row>
              <v-col cols="6">
                <h4 class="chart-title">송배전망 - NWAs 탄소배출량 비교</h4>
                <canvas ref="carbonBarChart" height="220"></canvas>
              </v-col>
              <v-col cols="6">
                <h4 class="chart-title">송배전망 - NWAs 탄소배출량 비율</h4>
                <canvas ref="carbonDoughnutChart" height="220"></canvas>
              </v-col>
            </v-row>
          </v-card>
        </v-col>

        <!-- 우측: 데이터 테이블 -->
        <v-col cols="5">
          <v-card class="table-card" outlined>
            <div class="table-header">
              <span>구분</span>
              <span class="unit-label">단위 : tCO₂/MWh</span>
            </div>

            <v-data-table :headers="carbonTableHeaders" :items="carbonTableItems" :items-per-page="-1"
              hide-default-footer density="compact" virtual-scroll="false" style="max-height: none; overflow: visible">
              <template v-slot:item="{ item }">
                <tr>
                  <td class="text-left font-weight-bold category-col">
                    {{ item.category }}
                  </td>
                  <td v-for="(topology, idx) in topologyList" :key="idx" class="text-right">
                    {{ item[`list${idx + 1}`] }}
                  </td>
                </tr>
              </template>
            </v-data-table>

          </v-card>
        </v-col>
      </v-row>
    </v-container>

    <!-- 하단: 보고서 버튼 -->
    <div class="footer-bar">
      <!-- <v-btn color="primary" class="report-btn" @click="exportAllToPDF"> -->

      <v-btn color="primary" class="report-btn">
        보고서 생성
      </v-btn>
    </div>
  </div>
</template>


<script setup>
import { ref, onMounted, watch, nextTick, computed } from "vue";
import Chart from "chart.js/auto";
import ChartDataLabels from "chartjs-plugin-datalabels";
// import html2pdf from "html2pdf.js";
import { useTopologyStore } from "../store/topologyStore.js";
import { storeToRefs } from "pinia";

// 플러그인 등록
Chart.register(ChartDataLabels);

// ==============================
// 🧩 Store 연결
// ==============================
const topologyStore = useTopologyStore();
const { topologyList } = storeToRefs(topologyStore);

// 상단 탭 상태
const selectedTab = ref("cost");


// ==============================
// 🌱 Carbon Chart refs
// ==============================
const carbonBarChart = ref(null);
const carbonDoughnutChart = ref(null);

let carbonBarChartInstance = null;
let carbonDoughnutChartInstance = null;

// 탄소 테이블 데이터
const carbonTableItems = ref([]);


// 온실가스 배출 계수
const CARBON_FACTOR = {
  석탄화력: 820,
  원전: 12,
  소수력: 24,
  가스복합: 490,

  태양광: 48,
  풍력: 11,
  해상풍력: 12,

  ESS: 48,     // 태양광 대체 개념
  EV: 490,
  EVC: 490,
  DR: 490,
  VPP: 490
};

// ==============================
// 🧭 Topology 데이터 변환
// ==============================
const arrayToMap = (topologyList) => {

  return topologyList.map((route) => {
    // route 배열이 존재하는지 먼저 확인
    if (!Array.isArray(route)) return new Map();

    const entries = route
      .filter((node) => node && typeof node === "object") // ✅ null/undefined 방지
      .map((node) => {
        // ✅ label이 없을 때 대비
        const label = node.label?.replace(/-[A-Z]$/i, "") || "";
        const props = Array.isArray(node.property) ? node.property : [];
        const formatted = {};

        // ✅ property 값 안전 변환
        props.forEach((prop) => {
          const name = prop?.name;
          const values = Array.isArray(prop?.values) ? prop.values : [];
          if (!name || !values.length) return;

          if (values.length === 1 && "data" in values[0]) {
            formatted[name] = values[0].data;
          } else if (values.every((v) => "name" in v && "data" in v)) {
            formatted[name] = values.reduce((obj, v) => {
              if (!v.name) return obj;
              obj[v.name] = v.data;
              return obj;
            }, {});
          }
        });

        // ✅ 원본 속성 안전 보존
        formatted.property = node.property ?? [];
        formatted.lat = node.lat ?? 0;
        formatted.lng = node.lng ?? 0;
        formatted.id = node.id ?? null; // ✅ 핵심 부분 (NWAs 탐색용)

        return [label, formatted];
      });

    return new Map(entries);
  });
};

const map_topologyList = computed(() => arrayToMap(topologyList.value));


// ==============================
// 🔽 Topology 선택
// ==============================
const selectedGroupIndex = ref(0);
const groupOptions = computed(() =>
  topologyList.value.map((_, idx) => ({
    title: `Topology List ${idx + 1}`,
    value: idx,
  }))
);

const getSelectedList = computed(() => {
  if (!topologyList.value || topologyList.value.length === 0) return [];

  const index = selectedGroupIndex.value;
  const selected = topologyList.value[index];

  return Array.isArray(selected) ? selected : [];
});
// ==============================
// 📊 Chart refs
// ==============================
const barChart = ref(null);
const doughnutChart = ref(null);
let barChartInstance = null;
let doughnutChartInstance = null;

// ==============================
// 📄 Table 데이터
// ==============================
const tableHeaders = computed(() => {
  const headers = [
    { title: "구분", key: "category", align: "start" }
  ];

  topologyList.value.forEach((_, idx) => {
    headers.push({
      title: `List ${idx + 1}`,
      key: `list${idx + 1}`,
      align: "end"
    });
  });

  return headers;
});

const tableItems = ref([]);

// ==============================
// 📏 거리 계산 함수 (절대 유지)
// ==============================
const getDistance = (lat1, lng1, lat2, lng2) => {
  const R = 6371e3; // m
  const rad = Math.PI / 180;
  const phi1 = lat1 * rad;
  const phi2 = lat2 * rad;
  const dPhi = (lat2 - lat1) * rad;
  const dLambda = (lng2 - lng1) * rad;

  const a =
    Math.sin(dPhi / 2) ** 2 +
    Math.cos(phi1) * Math.cos(phi2) * Math.sin(dLambda / 2) ** 2;
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return (R * c) / 1000; // km
};

// ==============================
// 💰 비용 계산 (절대 유지)
// ==============================

const calcCostData = (group, nwasNodes) => {


  const safeNum = (val) => {
    const num = Number(val);
    return isNaN(num) || !isFinite(num) ? 0 : num;
  };

  // ------------------------------
  // 🔹 노드 추출
  // ------------------------------
  const demand =
    group.get("수요지역") || group.get("수요지역-A") || group.get("수요지역-B");

  const k765 = group.get("765kV") || group.get("765kV-A");
  const k345 = group.get("345kV") || group.get("345kV-A");
  const k154 = group.get("154kV") || group.get("154kV-A");
  const k22 = group.get("22.9kV") || group.get("22.9kV-A");


  // ------------------------------
  // 🔹 거리 계산
  // ------------------------------
  let distance = 50;
  if (demand && k22 && demand.lat && k22.lat)
    distance = getDistance(demand.lat, demand.lng, k22.lat, k22.lng);

  // ------------------------------
  // ⚙️ 송전망 공통 계산 함수
  // ------------------------------
  const getTransmissionCost = (node, defaultLoss = 0.03) => {
    if (!node) return 0;

    const prop = node.property || [];
    const connect =
      prop.find((p) => p.name.includes("송전접속단가_1년사용기존"))?.values ||
      [];
    const loss =
      prop.find((p) => p.name.includes("송전손실단가_1년사용기존"))?.values ||
      [];

    const findVal = (arr, key) =>
      safeNum(arr.find((v) => v.name.replace(/\s/g, "").includes(key))?.data);

    const baseUnit = findVal(connect, "기본") || 667.61;
    const useUnit = findVal(connect, "사용") || 1.42;
    const lossUnit = findVal(loss, "석탄화력") || defaultLoss;

    const demandProp = demand?.property?.[0]?.values || [];
    const demandMW = safeNum(
      demandProp.find((v) => v.name.includes("수요"))?.data
    );
    const demand_kW = demandMW * 1000;
    const dailyUsageHr = 8;

    // ✅ 단위 보정 + 고정 건설비 반영
    const buildUnit = safeNum(
      node.property?.[0]?.values.find((v) => v.name.includes("건설단가"))?.data
    );
    const baseCost =
      buildUnit > 0
        ? buildUnit * 1_000_000 * 50
        : node.label?.includes("765")
          ? 5_700_000_000
          : node.label?.includes("345")
            ? 2_060_000_000
            : node.label?.includes("154")
              ? 102_000_000
              : 0;

    const construction = baseCost;
    const connection =
      demand_kW * useUnit * dailyUsageHr * 365 + demand_kW * baseUnit;
    const lossCost = demand_kW * (lossUnit / 1000) * dailyUsageHr * 365;

    return construction + connection + lossCost;
  };

  // ------------------------------
  // ⚙️ 송배전망 계산
  // ------------------------------
  const cost765 = getTransmissionCost(k765);
  const cost345 = getTransmissionCost(k345);
  const cost154 = getTransmissionCost(k154);

  const prop22 =
    k22?.property?.find((p) => p.name.includes("배전망구축단가"))?.values || [];

  const expansionType = k22?.expansionType || "신축"; // ✅ 저장된 선택값 불러오기
  const powerType = k22?.powerType || "AC"; // ✅ 저장된 선택값 불러오기
  const groupKey = `${expansionType}-${powerType}`;

  // ✅ 선택된 조합에 해당하는 그룹만 합산
  const filteredValues = prop22.filter((v) => v.group === groupKey);
  const distribSum = filteredValues.reduce(
    (sum, v) => sum + safeNum(v.data),
    0
  );
  const cost229 = distance * distribSum * 10_000;

  // ------------------------------
  // ⚙️ NWAs 계산
  // ------------------------------
  const calcNWAsCost = (nodes) => {
    const total = {}

    const safeNum = (v) => {
      const n = Number(v)
      return isNaN(n) ? 0 : n
    }

    // 설치용량(MW)
    const getCapacityMW = (node) => {
      console.log("설치용량 >> ", node)
      const baseProp = node.property?.find(p =>
        Array.isArray(p.values) &&
        p.values.some(v => v.name === "설치용량")
      )

      return safeNum(
        baseProp?.values?.find(v => v.name === "설치용량")?.data
      )
    }

    // 구축단가 property
    const getCostProp = (node) =>
      node.property?.find(p => p.name?.includes("구축단가"))

    // 연계비 구간 선택
    const pickGridCost = (values, capacityMW) => {
      if (capacityMW <= 1) {
        return values.find(v => v.name.includes("1MW이하"))
      }
      if (capacityMW <= 50) {
        return values.find(v => v.name.includes("1MW~50MW"))
      }
      return values.find(v => v.name.includes("50MW이상"))
    }

    nodes.forEach(node => {
      const label = node.key?.replace(/-A|-B/g, "") || "NWAs"
      const expansionType = node.expansionType || "신축"

      const capacityMW = getCapacityMW(node)
      const capacityKW = capacityMW * 1000

      const costProp = getCostProp(node)
      const values = costProp?.values || []
      const buildValues = values.filter(v => v.group === expansionType)

      let cost = 0

      switch (label) {

        // ==================================================
        // ESS / 태양광 / 풍력
        // 수식:
        // (건설·설비비 + 유지비 + 인허가비) × 용량
        // + 연계비(조건부)
        // ==================================================
        case "ESS":
        case "태양광":
        case "풍력": {
          let unitCostKW = 0       // 거래단가
          let connectCost = 0      // 연계비
          let fixedCost = 0        // 고정비

          // 1️⃣ 거래단가(kW)
          buildValues.forEach(v => {
            if (
              v.name.includes("설비비용") ||
              v.name.includes("건설비용") ||
              v.name.includes("유지비용") ||
              v.name.includes("인허가비용")
            ) {
              unitCostKW += safeNum(v.data)
            }
          })

          // 2️⃣ 연계비 (부과 기준 충족 시)
          // 태양광/풍력/ESS: 10MW 이상
          if (capacityMW >= 10) {
            const grid = pickGridCost(buildValues, capacityMW)
            if (grid?.data) {
              connectCost += safeNum(grid.data) * 1000 * capacityKW
            }
          }

          // 3️⃣ 고정비
          const fixed = buildValues.find(v =>
            v.unit?.includes("억원/고정비")
          )
          if (fixed?.data) {
            fixedCost += safeNum(fixed.data) * 100000000
          }

          cost =
            unitCostKW * 1000 * capacityKW
            + connectCost
            + fixedCost

          break
        }

        // ==================================================
        // 해상풍력
        // 연계비 필수(대규모)
        // ==================================================
        case "해상풍력": {
          let unitCostKW = 0
          let fixedCost = 0

          buildValues.forEach(v => {
            if (v.unit?.includes("천원/kW")) {
              unitCostKW += safeNum(v.data)
            }
            if (v.unit?.includes("억원/고정비")) {
              fixedCost += safeNum(v.data) * 100000000
            }
          })

          cost = unitCostKW * 1000 * capacityKW + fixedCost
          break
        }

        // ==================================================
        // EV
        // 연계비 없음
        // ==================================================
        case "EV": {
          let unitCostKW = 0

          buildValues.forEach(v => {
            if (
              v.name.includes("차량") ||
              v.name.includes("유지")
            ) {
              unitCostKW += safeNum(v.data)
            }
          })

          cost = unitCostKW * 1000 * capacityKW
          break
        }

        // ==================================================
        // EVC
        // 연계비 기준: 300kW 이상
        // ==================================================
        case "EVC": {
          let unitCostKW = 0
          let connectCost = 0

          buildValues.forEach(v => {
            if (v.unit?.includes("천원/kW")) {
              unitCostKW += safeNum(v.data)
            }
          })

          if (capacityKW >= 300) {
            const grid = pickGridCost(buildValues, capacityMW)
            if (grid?.data) {
              connectCost += safeNum(grid.data) * 1000 * capacityKW
            }
          }

          cost = unitCostKW * 1000 * capacityKW + connectCost
          break
        }

        // ==================================================
        // DR / VPP
        // 통신 연계비 필수
        // ==================================================
        case "DR":
        case "VPP": {
          let unitCostKW = 0
          let commCost = 0

          buildValues.forEach(v => {
            if (
              v.name.includes("구축비") ||
              v.name.includes("유지비용")
            ) {
              unitCostKW += safeNum(v.data)
            }
            if (v.name.includes("통신")) {
              commCost += safeNum(v.data) * 1000 * capacityKW
            }
          })

          cost = unitCostKW * 1000 * capacityKW + commCost
          break
        }

        default:
          cost = 0


      }

      console.group(`[NWAs 검산] ${label}`)
      console.log("설치용량(MW):", capacityMW)
      console.log("확장유형:", expansionType)
      console.log("사용된 단가 항목:", buildValues)
      total[label] = Math.max(0, cost)
    })



    return total
  }


  console.log("nwasCosts", nwasNodes);

  const nwasCosts = calcNWAsCost(nwasNodes);

  const nwasSum = Object.values(nwasCosts)
    .map((v) => safeNum(v))
    .reduce((a, b) => a + b, 0);

  // ------------------------------
  // ⚙️ 합계 및 편익 계산
  // ------------------------------
  const transSum = safeNum(cost765) + safeNum(cost345) + safeNum(cost154) + safeNum(cost229);


  // ✅ 편익 및 총합 (NaN 방지)
  const benefit = safeNum(transSum - nwasSum);
  const total = safeNum(transSum + nwasSum + benefit);

  // ------------------------------
  // 📊 Chart.js 데이터 구성
  // ------------------------------
  const bar = {
    labels: ["배전망", "NWAs", "편익"],
    datasets: [
      { label: "765kV", data: [cost765, 0, 0], backgroundColor: "#6366F1" },
      { label: "345kV", data: [cost345, 0, 0], backgroundColor: "#60A5FA" },
      { label: "154kV", data: [cost154, 0, 0], backgroundColor: "#FBBF24" },
      { label: "22.9kV", data: [cost229, 0, 0], backgroundColor: "#34D399" },
      ...Object.entries(nwasCosts).map(([key, val], idx) => ({
        label: key,
        data: [0, val, 0],
        backgroundColor: [
          "#E879F9",
          "#10B981",
          "#F87171",
          "#3B82F6",
          "#F59E0B",
          "#6366F1",
          "#22C55E",
          "#0EA5E9",
        ][idx],
      })),
      { label: "B/C", data: [0, 0, benefit], backgroundColor: "#FDBA74" },
    ],
  };

  const doughnut = {
    labels: ["765kV", "345kV", "154kV", "22.9kV"],
    datasets: [
      {

        data: [cost229],
        // data: [cost765, cost345, cost154, cost229],
        backgroundColor: ["#6366F1", "#60A5FA", "#FBBF24", "#34D399"],
      },
    ],
  };

  // ------------------------------
  // 🧾 표 데이터 구성 (category 키 통일)
  // ------------------------------
  const nwasLabels = [
    "태양광",
    "풍력",
    "해상풍력",
    "ESS",
    "EV",
    "EVC",
    "DR",
    "VPP",
  ];

  const fmt = (num) => {
    const safe = safeNum(num);
    if (safe === 0) return "-"; // 🔸 0이면 하이픈 표시
    return Math.round(safe).toLocaleString("ko-KR", {
      maximumFractionDigits: 0,
    });
  };


  const table = [
    { category: "765kV", value: fmt(cost765) },
    { category: "345kV", value: fmt(cost345) },
    { category: "154kV", value: fmt(cost154) },
    { category: "22.9kV", value: fmt(cost229) },
    { category: "배전망 합계", value: fmt(transSum) },

    ...nwasLabels.map(k => ({
      category: k,
      value: safeNum(nwasCosts[k]) > 0 ? fmt(nwasCosts[k]) : "-",
    })),


    { category: "NWAs 합계", value: fmt(nwasSum) },
    { category: "편익비용", value: fmt(benefit) },

  ];


  // console.log('topologyList : ', topologyList.value)
  // console.log("distance:", distance);
  // console.log("distribSum:", distribSum);
  // console.log(
  //   "filteredValues:",
  //   prop22.filter(v => v.group === groupKey)
  // );



  return { bar, doughnut, table, total };
};

