      type: "bar",
      data: bar,
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { stacked: true, grid: { display: false } },
          y: {
            stacked: true,
            beginAtZero: true,
            ticks: {
              callback: (v) => (v / 1_000_000).toLocaleString() + "백만",
            },
          },
        },
        plugins: {
          legend: {
            position: "bottom",
            labels: { usePointStyle: true, boxWidth: 10, padding: 15 },
          },
          tooltip: {
            callbacks: {
              label: function (context) {
                const value = context.parsed.y;
                // ✅ 소수점 없이 천 단위 콤마 추가
                return `${Math.round(value).toLocaleString("ko-KR")} 원`;
              },
            },
          },
          datalabels: {
            anchor: "center",
            align: "center",
            color: "#000",
            font: { weight: "bold" },
            formatter: (v) =>
              v > 0
                ? `${Math.round(v / 1_000_000).toLocaleString("ko-KR")} 백만`
                : "",
          },
        },
      },
    });
  }

  // ✅ 도넛 차트 (송배전망 vs NWAs 총합)
  if (doughnutChart.value) {
    const ctx = doughnutChart.value.getContext("2d");
    if (doughnutChartInstance) doughnutChartInstance.destroy();

    const transSum = sumTransmission;
    const nwasSum = sumNWAs;
    const totalSum = transSum + nwasSum;

    const doughnutData = {
      labels: ["배전망", "NWAs"],
      datasets: [
        {
          data: [transSum, nwasSum],
          backgroundColor: ["#6A5DFF", "#FF6B6B"],
          borderWidth: 0,
        },
      ],
    };

    doughnutChartInstance = new Chart(ctx, {
      type: "doughnut",
      data: doughnutData,
      options: {
        responsive: true,
        maintainAspectRatio: false,
        cutout: "70%",
        plugins: {
          legend: {
            position: "bottom",
            labels: {
              usePointStyle: true,
              boxWidth: 10,
              padding: 20,
              generateLabels: (chart) => {
                const data = chart.data.datasets[0].data;
                const labels = chart.data.labels;
                const total = data.reduce((a, b) => a + b, 0);
                return labels.map((label, i) => {
                  const val = data[i];
                  const percent =
                    total > 0 ? ((val / total) * 100).toFixed(1) : 0;
                  return {
                    text: `${label} : ${Math.round(
                      val / 1_000_000
                    ).toLocaleString("ko-KR")}백만 (${percent}%)`,
                    fillStyle: chart.data.datasets[0].backgroundColor[i],
                    hidden: false,
                    index: i,
                  };
                });
              },
            },
          },
          datalabels: {
            color: "#fff", // ✅ 도넛 위 글씨(회색 숫자) → 흰색으로 변경
            align: "center",
            anchor: "center",
            font: {
              weight: "bold",
              size: 14,
            },
            formatter: (v) => {
              if (v <= 0) return "";
              return `${Math.round(v / 1_000_000).toLocaleString(
                "ko-KR"
              )} 백만`;
            },
          },
          tooltip: {
            callbacks: {
              label: (ctx) => {
                const val = ctx.raw;
                const percent = ((val / totalSum) * 100).toFixed(1);
                return `${ctx.label}: ${Math.round(
                  val / 1_000_000
                ).toLocaleString("ko-KR")}백만 (${percent}%)`;
              },
            },
          },
        },
      },
      plugins: [
        {
          id: "centerText",
          beforeDraw(chart) {
            const { width, height, ctx } = chart;
            const total = chart.data.datasets[0].data.reduce(
              (a, b) => a + b,
              0
            );
            ctx.save();
            ctx.font = "bold 28px Pretendard";
            ctx.fillStyle = "#000";
            ctx.textAlign = "center";
            ctx.textBaseline = "middle";
            ctx.fillText(
              Math.round(total / 1_000_000).toLocaleString("ko-KR"),
              width / 2,
              height / 2
            );
            ctx.font = "16px Pretendard";
            ctx.fillText("총 건설비용 (백만)", width / 2, height / 2 + 30);
            ctx.restore();
          },
        },
      ],
    });
  }

  // ✅ 테이블 최종 반영
  tableItems.value = table;
  console.table(tableItems.value);
};

