// 탄소배출량 계산
const GENERATION_TYPES = new Set([
  "석탄화력",
  "원전",
  "소수력",
  "가스복합"
]);

const getTotalDemandMW = (topologyGroups) => {
  let total = 0;

  topologyGroups.forEach(group => {
    total += getDemandMW(group);
  });

  return total;
};


const getNWADemandMW = (group, energyType) => {
  let total = 0;

  if (!group || typeof group.forEach !== "function") return 0;

  group.forEach((node, key) => {
    // 🔑 key 자체가 에너지원 이름
    if (key !== energyType) return;

    node.property?.forEach(prop => {
      prop.values?.forEach(v => {
        if (v.name === "여유용량") {
          total += Number(v.data) || 0;
        }
      });
    });
  });

  return total;
};

const calcCarbon = ({ capacityMW, dailyHour, factor }) => {
  const mw = Number(capacityMW) || 0;
  const h = Number(dailyHour) || 0;
  const f = Number(factor) || 0;

  return mw * h * 365 * f;
};

const extractEnergyTypesFromTopology = (group) => {
  const types = new Set();
  if (!group || typeof group.forEach !== "function") return types;

  group.forEach((_node, key) => {
    // 🔑 key 자체가 이미 정규화된 에너지원 이름
    if (CARBON_FACTOR[key]) {
      types.add(key);
    }
  });

  return types;
};

const getDemandMW = (group) => {
  const demand =
    group.get("수요지역") ||
    group.get("수요지역-A") ||
    group.get("수요지역-B");

  if (!demand) return 0;

  const demandMW = Number(
    demand.property?.[0]?.values?.find(v => v.name.includes("수요"))?.data
  );

  return isNaN(demandMW) ? 0 : demandMW;
};

const calcCarbonTableByTopology = (group, allTopologyGroups) => {
  const dailyHour = 8;

  const activeTypes = extractEnergyTypesFromTopology(group);

  const categories = [
    "석탄화력", "원전", "소수력", "가스복합",
    "태양광", "풍력", "해상풍력",
    "ESS", "EV", "EVC", "DR", "VPP"
  ];

  const result = {};

  categories.forEach(cat => {
    if (!activeTypes.has(cat)) {
      result[cat] = 0;
      return;
    }

    // ✅ 여기서 capacityMW 결정
    const capacityMW = GENERATION_TYPES.has(cat)
      ? getTotalDemandMW(allTopologyGroups)   // 발전소
      : getNWADemandMW(group, cat);            // NWA

    result[cat] = calcCarbon({
      capacityMW,
      dailyHour,
      factor: CARBON_FACTOR[cat]
    });
  });

  return result;
};

const buildCarbonTable = () => {
  const categories = [
    "석탄화력", "원전", "소수력", "가스복합",
    "태양광", "풍력", "해상풍력",
    "ESS", "EV", "EVC", "DR", "VPP"
  ];

  return categories.map(cat => {
    const row = { category: cat };
    for (let i = 1; i <= topologyList.value.length; i++) {
      row[`list${i}`] = "-";
    }
    return row;
  });
};

const createCarbonView = async () => {
  await nextTick();

  if (!topologyList.value.length) return;

  // =========================
  // 1️⃣ 테이블 생성
  // =========================
  const table = buildCarbonTable();

  for (let i = 0; i < topologyList.value.length; i++) {
    const group = map_topologyList.value[i];
    if (!group) continue;

    const carbonMap = calcCarbonTableByTopology(group, map_topologyList.value);

    table.forEach(row => {
      const value = carbonMap[row.category];
      row[`list${i + 1}`] =
        value > 0
          ? Math.round(value).toLocaleString("ko-KR")
          : "-";
    });
  }

  carbonTableItems.value = table;

  // =========================
  // 2️⃣ 선택 Topology 차트
  // =========================
  const selectedGroup =
    map_topologyList.value[selectedGroupIndex.value];

  if (!selectedGroup) return;

  const carbonMap =
    calcCarbonTableByTopology(selectedGroup, map_topologyList.value);

  drawCarbonCharts(carbonMap);
};

